/* [categoría, respuesta, [5 pistas de vaga a específica], reseña] */
L.quien=[
["Personaje","Seah de Pato",["Mi tribu era pobre en guerreros.","De niña peleé uno contra diez, entre risas.","Salí de viaje con el arma más valiosa de mi pueblo.","Le di a Bane un vino de efecto retardado antes de su duelo.","Soy una orca de la tribu Pato y mi arma es el Bastón del Lago."],"La orca del Lago Kcud."],
["Personaje","Vina Miceus",["Me moldearon desde bebé para servir a un reino autoritario.","Lideré redadas para apresar opositores y rebeldes.","Mi arma es un mandoble llamado «Miel».","Pedí tiempo fuera y compartí un té con un anciano inmortal.","Fui la primera en unirme al campamento de Caleus."],"La guerrera construida desde la cuna."],
["Personaje","Tomah de la Luz de Xora",["Mi padre me crió solo.","Quise sorprenderlo alistándome como arquero.","Mis resultados con el arco fueron desastrosos.","Entré a un campamento con una mentira sobre mi hombro.","Soy de Myrelith, en Luminarae Luxor."],"El arquero frustrado."],
["Personaje","Valmey Sialí",["Huí de mi madrastra a los once años.","Aprendí pintura y violín como artista callejero.","Soy abogado defensor.","Defendí a un goblin acusado de espionaje.","Tengo un pacto con Kiprika que me niego a respetar."],"El abogado del puerto."],
["Personaje","Seilá Anamé",["Crecí acogiendo peregrinos en mi casa.","Una caravana fingida asaltó mi hogar.","Mi padre se hundió en una tristeza de la que nunca se recuperó.","Me volví devota del Ganorismo en Suminé.","Busco comprender la tristeza misma para poder curarla."],"La que no vuelve a confiar ciegamente."],
["Personaje","Lael Anamé",["Fui amigo de infancia de un goblin.","Escapé del Presidio de Krahn.","En mi bautismo me obligaron a decapitar a un fugitivo.","Desde entonces no volví a tocar esa espada.","Prefiero las herramientas de la granja, que no se manchan."],"El que dejó la espada."],
["Personaje","Puj",["Soy un orco gris e imponente.","Una cicatriz marca uno de mis ojos.","Gobierno después de Malakar.","Presido un torneo junto a un emperador inmortal.","Soy el dictador de Umbra."],"El orco que Zarick tanto temía."],
["Personaje","Oci",["Soy emperador de un reino.","Soy inmortal.","Soy semidiós.","Mi padre es Ape.","Presido el Torneo de los Dos Emperadores en mi reino."],"El inmortal de Skaldrum."],
["Personaje","Luminara IV",["Gobierno una teocracia de torres flotantes.","Mi diosa es la de la pureza espiritual.","Mi nación celebra un día de héroes.","Casi aniquilo a tres visitantes a quienes salvaron unos semidioses.","Soy la reina de Luminarae Luxor."],"La reina de Luxor."],
["Personaje","Evelyn von Grace",["Crecí en una ciudad flotante.","Mi salud era frágil.","Aprendí el idioma de la cultura orca.","Un orco me salvó de una bestia lupina.","Mi hijo nació en Umbra."],"La madre de Zarick."],
["Personaje","Heiss von Grace",["Soy un hombre de ciencia y de magia.","Busco el origen divino del poder.","Sellé un pacto con una tribu que custodiaba una caverna.","Traicioné a esa tribu al descubrir un romance.","Soy el abuelo de Zarick."],"El padre de Evelyn."],
["Personaje","Alnasi",["Soy el segundo de ocho experimentos.","Nací en la Ciénaga.","Crío y comando a mis hermanos en nombre de otro.","Mi creador es Tsuji.","Soy el padre no biológico y líder de los Ocho de Negatt."],"Líder de los Ocho."],
["Personaje","Tsuji",["Soy investigador de Negatt.","Demostré algo que parecía solo leyenda.","Un espíritu de bestia puede imponerse por la fuerza a un humano.","Mis hijos son mis propios experimentos.","Soy el padre biológico de los Ocho de Negatt."],"El creador de los Ocho."],
["Personaje","Caelum",["Soy el menor de ocho.","Me criaron con un entrenamiento y una nutrición estrictos.","Soy un experto en combate.","Aplico lógica y matemática a la pelea, pero soy bruto fuera de ella.","No sé que soy un experimento."],"El 8° de los Ocho de Negatt."],
["Personaje","Khagzol «Zodd» Shazolg",["Soy un orco de una tribu noble.","Mi tribu custodiaba la Caverna Mortuoria.","Porto una espada de carnicero épica.","Salvé a una joven de una bestia lupina.","Soy el padre de Zarick."],"Líder de Zudodh Ez."],
["Personaje","Chunchunmaru",["Parezco un androide.","Puedo crecer.","Tengo características biológicas.","Una operación de recuperación con autómatas me buscó.","Una IA de Lumis está relacionada con esa búsqueda."],"El androide que crece."],
["Deidad","Ape",["Soy una de las diez fuerzas del cosmos.","No soy malvado: represento el final inevitable de todo.","Se dice que corrompí en secreto a la civilización original.","Mi enemistad con mi contrapunto provocó tormentas cósmicas.","Skaldrum me venera y el emperador Oci es mi hijo."],"Entropía y oscuridad."],
["Deidad","Dacama",["Soy una de las diez fuerzas del cosmos.","Camino solo, sin un par.","Soy el cronista universal.","Aseguro que la entropía de Ape se manifieste.","Soy el Tiempo."],"El cronista universal."],
["Deidad","Tapiem",["Soy una de las diez fuerzas del cosmos.","Carezco de forma.","Mi presencia se ve en cada órbita planetaria.","Evito que todo se desmorone.","Soy la Gravedad."],"El tejedor invisible."],
["Deidad","Millot",["Soy una de las diez fuerzas del cosmos.","Siembro la materia prima y las ideas.","Opero un ciclo eterno con mi hermano.","Mi hermano elimina lo viejo y débil.","Soy la Creación."],"Creación."],
["Nación","Skaldrum",["Mi estética mezcla lo grecorromano con armamento avanzado.","Mi sociedad arrastra una fuerte desigualdad entre clases.","Soy un feudalismo extremo.","Venero a Ape.","Aquí se celebró el Torneo de los Dos Emperadores."],"El Reino de Hierro y Honor."],
["Nación","Luminarae Luxor",["Mis torres y templos flotan.","Soy una teocracia jerárquica.","Mi diosa es Xora.","Celebro el Día de los Héroes, el día 103.","Mi reina es Luminara IV."],"Reino de Fe y Elevación."],
["Nación","Boro",["Mi aire está contaminado y mis luces rotas.","Soy el refugio de los restos.","Hay mafias, clanes y luchas de robots.","Aquí está el templo de Tharnok.","Me independicé en el año 333."],"El Refugio de los Restos."],
["Nación","Psybernia",["Estoy cerrada sobre mí misma.","Corren rumores de laboratorios ocultos.","Aquí se experimenta con seres vivos.","Nadie entra ni sale sin permiso de mi soberana.","Mi gente dice que somos todos primos."],"El horror bajo el silencio."],
["Nación","Markivton",["Soy un estado portuario.","Vivo de navegación, comercio y tripulaciones.","No tengo ley formal, pero sí un código propio.","Soy el hogar de la familia Dust-Clement.","Soy la nación de piratas y anarquía."],"Nación de piratas y anarquía."],
["Nación","Sylvaris",["Soy una necrocracia timocrática.","Me gobierna una mente colmena vegetal.","Mis ancestros incorpóreos dirigen mi gobierno.","Las cenizas de Sinfalía queman mi conexión espiritual.","De aquí fue expulsada la Tribu Zzamua."],"La Urdimbre de Sylvaris."],
["Nación","Disnjav",["Soy sinónimo de peligro invisible.","Nadie sabe si es mi aire, mi agua o mi tierra.","Conviene no quedarse mucho tiempo.","Mi vecina del norte es Pongí.","Soy la tierra enferma."],"Asociada a lo tóxico."],
["Lugar","Anamé",["Soy el pueblo más poblado de mi nación, con 520 habitantes.","Soy un nexo comercial en un bosque templado.","Mi escuela es la de Leyes y Comercio.","Valmey nació aquí.","Seilá y Lael crecieron en mí."],"Pueblo de Sinfalía."],
["Lugar","Fuana",["Mis forjas son térmicas.","Estoy en una zona volcánica.","Mi escuela es la de Metalurgia y el Fuego.","Un herrero draconiano trabajaba aquí.","Un goblin aprendió vidrio, alquimia y forja en mí."],"Pueblo de Sinfalía."]
];

